{"source": "def investigate(context, acquire):
    receipts = acquire("history")

    def run(actions, mode, trig, chan):
        state = {}
        tx = {"main": None, "other": None}
        total = {"main": 0, "other": 0}
        last = {"main": 0, "other": 0}
        log = [0]

        def write(conn, op, key, value):
            if op == "put":
                if mode == "ignore":
                    if key in state:
                        return 0
                    state[key] = value
                    n = 1
                else:
                    state[key] = value
                    n = 1
                if trig:
                    log[0] += 1
                return n
            if op == "update":
                if key in state:
                    state[key] = value
                    n = 1
                else:
                    n = 0
                if trig and n > 0:
                    log[0] += 1
                return n
            if op == "delete":
                if key in state:
                    del state[key]
                    return 1
                return 0
            return 0

        for act in actions:
            op = act.get("op")
            conn = act.get("connection", "main")
            if op == "begin":
                tx[conn] = dict(state)
            elif op == "commit":
                if tx[conn] is not None:
                    state = tx[conn]
                    tx[conn] = None
            elif op == "rollback":
                tx[conn] = None
            else:
                key = act.get("key")
                value = act.get("value", 0)
                if tx[conn] is not None:
                    saved = state
                    state = tx[conn]
                    n = write(conn, op, key, value)
                    tx[conn] = state
                    state = saved
                else:
                    n = write(conn, op, key, value)
                total[conn] += n
                last[conn] = n

        if chan == "changes":
            return last["main"]
        if chan == "total_main":
            return total["main"]
        return total["main"] + total["other"]

    def committed(actions, mode):
        state = {}
        tx = {"main": None, "other": None}
        for act in actions:
            op = act.get("op")
            conn = act.get("connection", "main")
            if op == "begin":
                tx[conn] = dict(state)
            elif op == "commit":
                if tx[conn] is not None:
                    state = tx[conn]
                    tx[conn] = None
            elif op == "rollback":
                tx[conn] = None
            else:
                key = act.get("key")
                value = act.get("value", 0)
                if tx[conn] is not None:
                    saved = state
                    state = tx[conn]
                    if op == "put":
                        if mode == "ignore":
                            if key not in state:
                                state[key] = value
                        else:
                            state[key] = value
                    elif op == "update":
                        if key in state:
                            state[key] = value
                    elif op == "delete":
                        if key in state:
                            del state[key]
                    tx[conn] = state
                    state = saved
                else:
                    if op == "put":
                        if mode == "ignore":
                            if key not in state:
                                state[key] = value
                        else:
                            state[key] = value
                    elif op == "update":
                        if key in state:
                            state[key] = value
                    elif op == "delete":
                        if key in state:
                            del state[key]
        return state

    modes = ["ignore", "replace"]
    trigs = [False, True]
    chans = ["changes", "total_main", "total_both"]

    candidates = []
    for mode in modes:
        for trig in trigs:
            for chan in chans:
                ok = True
                for r in receipts:
                    acts = r.get("actions", [])
                    obs = r.get("observed", {})
                    if run(acts, mode, trig, chan) != obs.get("channel"):
                        ok = False
                        break
                    st = committed(acts, mode)
                    if len(st) != obs.get("committed_count"):
                        ok = False
                        break
                    if sum(st.values()) != obs.get("committed_sum"):
                        ok = False
                        break
                if ok:
                    candidates.append((mode, trig, chan))

    if not candidates:
        return {"value": None, "unresolved": True}

    goal = context.get("goal")
    actions = context.get("actions", [])
    results = set()
    for mode, trig, chan in candidates:
        if goal == "channel":
            results.add(run(actions, mode, trig, chan))
        else:
            st = committed(actions, mode)
            if goal == "committed_count":
                results.add(len(st))
            else:
                results.add(sum(st.values()))

    if len(results) == 1:
        return {"value": results.pop(), "unresolved": False}
    return {"value": None, "unresolved": True}
